def solve_n_queens(n=8):
    cols = [-1]*n
    def backtrack(r):
        if r == n:
            return True
        for c in range(n):
            ok = True
            for i in range(r):
                if cols[i] == c or abs(cols[i]-c) == abs(i-r):
                    ok = False
                    break
            if ok:
                cols[r] = c
                if backtrack(r+1):
                    return True
        return False
    if backtrack(0):
        return cols
    return None

sol = solve_n_queens(8)
print(sol)
